using System.IO;using System.Windows.Media.Imaging;using GymOS.Windows;
static class Program{
 [STAThread] static void Main(string[] args){var root=Path.Combine(Path.GetTempPath(),"gymos-brand-test-"+Guid.NewGuid());Directory.CreateDirectory(root);try{var logo="data:image/png;base64,"+Convert.ToBase64String(File.ReadAllBytes(args[0]));var store=new DesktopBranding(root);if(store.Load()!=null)throw new Exception("Unexpected cached brand");var brand=new ClubBrand("synthetic-owner","Synthetic Club",logo);var first=store.Apply(brand);if(first.image?.PixelWidth!=256||first.image.PixelHeight!=256||first.icon==null||!File.Exists(first.icon))throw new Exception("Icon not produced");using(var stream=File.OpenRead(first.icon)){var icon=BitmapDecoder.Create(stream,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);if(icon.Frames[0].PixelWidth!=256)throw new Exception("Invalid ICO");}if(store.Load()!=brand)throw new Exception("Brand not restored on startup");var next=store.Apply(brand with{Owner="other-owner"});if(next.icon==first.icon)throw new Exception("Cross-tenant icon path");foreach(var invalid in new[]{brand with{Logo="https://evil.invalid/icon.png"},brand with{Owner=""},brand with{Logo="data:image/png;base64,AA=="},brand with{Name="bad\nname"}}){bool rejected=false;try{store.Apply(invalid);}catch{rejected=true;}if(!rejected)throw new Exception("Unsafe branding accepted");}store.Apply(brand with{Logo=null});if(store.Load()?.Logo!=null)throw new Exception("Logo removal not persisted");store.Clear();if(store.Load()!=null)throw new Exception("Brand reset failed");Console.WriteLine("PASS: Windows PNG validation, ICO decode, startup restore, tenant-specific cache path, logo removal and reset");}finally{Directory.Delete(root,true);}}
}
